def deep_merge(s: str) -> str:
    """Compress a string using run-length encoding.

    Consecutive identical characters are replaced by the character
    followed by its count. Counts of 1 are omitted.

    Examples:
        "aaabbc" -> "a3b2c"
        "abcd"   -> "abcd"
        ""       -> ""
    """
    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1])
            if count > 1:
                result.append(str(count))
            count = 1

    result.append(s[-1])
    if count > 1:
        result.append(str(count))

    return "".join(result)


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_empty_string():
    assert deep_merge("") == ""


def test_single_character():
    assert deep_merge("a") == "a"


def test_no_repeats():
    assert deep_merge("abcd") == "abcd"


def test_all_same():
    assert deep_merge("aaaa") == "a4"


def test_basic_compression():
    assert deep_merge("aaabbc") == "a3b2c"


def test_alternating():
    assert deep_merge("abab") == "abab"


def test_single_repeats():
    assert deep_merge("aaabbbaaa") == "a3b3a3"


def test_two_chars():
    assert deep_merge("aa") == "a2"


def test_long_run():
    assert deep_merge("a" * 20) == "a20"


def test_mixed_lengths():
    assert deep_merge("aaabccccdd") == "a3bc4d2"


def test_whitespace():
    assert deep_merge("  aa  ") == " 2a2 2"


def test_digits_in_string():
    assert deep_merge("1112223") == "1322313"  # 1->3, 2->2, 3->1 -> "13" + "22" + "3" + "1" -> wait
    # "1112223" -> '1'×3, '2'×3, '3'×1 -> "13" + "23" + "3"
    assert deep_merge("1112223") == "13233"


def test_special_characters():
    assert deep_merge("!!@@@##") == "!2@3#2"


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

